/**
 * AD Sync Dispatcher Lambda
 *
 * Triggered by EventBridge on schedule (e.g. every 6 hours).
 * Queries amfa-configtable GSI (configtype-index) for all tenants with AD sync enabled,
 * then invokes the ad-sync-worker Lambda for each tenant asynchronously.
 */

import { randomUUID } from 'node:crypto';
import { DynamoDBClient, QueryCommand } from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';
import { isDedicatedWorkerArn, selectWorker } from './routing.mjs';
import { updateAdSyncConfig } from '../shared/ad-sync-config/index.mjs';

const dynamodb = new DynamoDBClient({});
const lambda = new LambdaClient({});

const STAGGER_DELAY_MS = 500;

async function queryConfigType(dynamodbClient, configtype) {
  const items = [];
  let lastEvaluatedKey;
  do {
    const queryResult = await dynamodbClient.send(new QueryCommand({
      TableName: process.env.CONFIG_TABLE,
      IndexName: 'configtype-index',
      KeyConditionExpression: 'configtype = :ct',
      ExpressionAttributeValues: { ':ct': { S: configtype } },
      ...(lastEvaluatedKey ? { ExclusiveStartKey: lastEvaluatedKey } : {}),
    }));
    items.push(...(queryResult.Items || []));
    lastEvaluatedKey = queryResult.LastEvaluatedKey;
  } while (lastEvaluatedKey);
  return items;
}

function readDedicatedState(item) {
  if (!item) return null;
  return {
    mode: item.mode?.S || 'shared',
    dedicatedLambdaArn: item.dedicatedLambdaArn?.S || null,
  };
}

export function createHandler({
  dynamodbClient = dynamodb,
  lambdaClient = lambda,
  sleep = (delay) => new Promise(resolve => setTimeout(resolve, delay)),
} = {}) {
  return async (event) => {
  const startTime = new Date().toISOString();
  console.log(JSON.stringify({ level: "INFO", event: "DISPATCHER_STARTED", timestamp: startTime, trigger: event?.source || "manual" }));

  try {
    const [allItems, dedicatedItems] = await Promise.all([
      queryConfigType(dynamodbClient, 'adSyncConfig'),
      queryConfigType(dynamodbClient, 'dedicatedIpState'),
    ]);
    const dedicatedStates = new Map(
      dedicatedItems.map(item => [item.id.S, readDedicatedState(item)]),
    );

    const allTenants = allItems.map((item) => {
      const config = JSON.parse(item.value?.S || "{}");
      return { tenantId: item.id.S, config };
    });

    const enabledTenants = allTenants.filter((t) => t.config.enabled === true);

    console.log(JSON.stringify({
      level: "INFO", event: "TENANTS_SCANNED",
      totalConfigs: allTenants.length, enabledCount: enabledTenants.length,
      enabledTenants: enabledTenants.map((t) => t.tenantId),
    }));

    if (enabledTenants.length === 0) {
      console.log(JSON.stringify({ level: "INFO", event: "NO_TENANTS_ENABLED", message: "No tenants with AD sync enabled" }));
      return { statusCode: 200, body: { dispatched: 0, message: "no_tenants_enabled" } };
    }

    // Fan-out: invoke worker for each tenant with stagger delay
    // Routing: if tenant has dedicated IP mode with a dedicated Lambda ARN,
    // invoke that Lambda; otherwise use the shared worker.
    const results = [];
    for (let i = 0; i < enabledTenants.length; i++) {
      const { tenantId } = enabledTenants[i];
      const dedicatedState = dedicatedStates.get(tenantId);

      // Determine which Lambda to invoke based on connectivity mode
      const networkMode = dedicatedState?.mode || 'shared';
      const workerFunction = selectWorker(
        dedicatedState,
        process.env.SYNC_WORKER_FUNCTION_NAME,
      );
      if (
        dedicatedState?.mode === 'dedicated'
        && dedicatedState.dedicatedLambdaArn
        && !isDedicatedWorkerArn(dedicatedState.dedicatedLambdaArn)
      ) {
        console.error(JSON.stringify({
          level: 'ERROR',
          event: 'INVALID_DEDICATED_ARN',
          tenantId,
          message: 'Dedicated worker ARN is invalid; falling back to shared worker',
        }));
      }

      let runId = null;
      try {
        console.log(JSON.stringify({
          level: "DEBUG", event: "DISPATCHING", tenantId,
          index: i + 1, total: enabledTenants.length,
          networkMode: networkMode || "shared",
          workerFunction,
        }));

        // Same ownership protocol as a manual Sync Now (amfa-470): stamp the
        // config with this run's id while marking it in progress, so an
        // overlapping older worker cannot report over this run, and this
        // worker cannot report over a newer one. Skip a tenant whose config
        // was disabled or removed since the scan.
        runId = randomUUID();
        const marked = await updateAdSyncConfig(dynamodbClient, tenantId,
          config => (config.enabled ? { lastSyncStatus: "in_progress", lastSyncRunId: runId } : null));
        if (!marked || !marked.enabled) {
          console.log(JSON.stringify({ level: "INFO", event: "DISPATCH_SKIPPED", tenantId, reason: "no_config_or_disabled" }));
          results.push({ tenantId, status: "skipped" });
          continue;
        }

        await lambdaClient.send(new InvokeCommand({
          FunctionName: workerFunction,
          InvocationType: "Event",
          Payload: JSON.stringify({ tenantId, runId }),
        }));

        results.push({ tenantId, status: "dispatched" });

        console.log(JSON.stringify({ level: "INFO", event: "DISPATCHED", tenantId, networkMode: networkMode || "shared" }));

        // Stagger to avoid Cognito API throttling
        if (i < enabledTenants.length - 1) {
          await sleep(STAGGER_DELAY_MS);
        }
      } catch (err) {
        console.error(JSON.stringify({
          level: "ERROR", event: "DISPATCH_FAILED", tenantId,
          error: err.message,
        }));
        results.push({ tenantId, status: "failed", error: err.message });
        // Do not leave this run's in_progress marker behind; only if it is still ours.
        if (runId) {
          await updateAdSyncConfig(dynamodbClient, tenantId, () => ({
            lastSyncStatus: "error",
            lastSyncTime: new Date().toISOString(),
            lastSyncError: "Scheduled sync could not be started.",
            lastSyncStats: undefined, // no result for this run
          }), { runId }).catch((e) => console.error(JSON.stringify({ level: "ERROR", event: "STATUS_UPDATE_FAILED", tenantId, error: e.message })));
        }
      }
    }

    const dispatched = results.filter((r) => r.status === "dispatched").length;
    const failed = results.filter((r) => r.status === "failed").length;

    console.log(JSON.stringify({
      level: "INFO", event: "DISPATCHER_COMPLETE",
      dispatched, failed, totalEnabled: enabledTenants.length,
    }));

    return {
      statusCode: 200,
      body: { dispatched, failed, tenants: results },
    };
  } catch (err) {
    console.error(JSON.stringify({
      level: "ERROR", event: "DISPATCHER_FAILED",
      error: err.message, stack: err.stack,
    }));
    return { statusCode: 500, body: { error: err.message } };
  }
  };
}

export const handler = createHandler();
